'use strict';
window.StudyHub=(()=>{
 const E=window.StudyEngine;let hanja={chapters:[]},dates={},view='today',selectedDay='',month='',chapterId='chapter-5',hanjaSearch='';
 const courseTitles=['Meeting Someone for the First Time','Everyday Life','Appointments','Asking Directions','Food','Public Rules','In the House','Shopping','Living in Korea','Problems','People','Health','Interests','Travel','Relationships'];
 const legacy=w=>!w.hanjaRef&&!w.studyRef;
 const dateLabel=d=>E.validDate(d)?new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Dubai'}):'Awaiting UAE notice';
 function init(data,examDates){hanja=data;dates=examDates;selectedDay=today();month=today().slice(0,7);state.curriculum=E.normalize(state.curriculum,today());chapterId=E.nextChapter(hanja.chapters,state.curriculum.chapters)?.id||hanja.chapters[0]?.id;return cards(data)}
 function cards(data){const out=[];for(const c of data.chapters){for(const h of c.characters){const ref={chapterId:c.id,chapter:c.number,section:c.section,character:h.hanja,page:h.page};const common={forms:[],meanings:[],occurrences:[],learned:false,categories:['Hanja',`Hanja · Chapter ${c.number}`],count:1,important:false,sourcePages:[],hanjaRef:ref};out.push({...common,id:'hj:char:'+c.number+':'+h.hanja,korean:h.hanja,forms:[h.hanja],answer:[h.koreanMeaning,h.reading,h.meaning].filter(Boolean).join(' · '),quizAnswer:[h.reading,h.meaning].filter(Boolean).join(' · '),memoryHint:{type:'Hanja root',text:[h.hanja,h.koreanMeaning,h.reading,h.meaning].filter(Boolean).join(' · ')},note:`${data.title||'Useful Hanja for Learners of Korean'} · Chapter ${c.number} · printed p.${h.page}. Recall the Korean reading and meaning, then recognise the root in Korean words.`});for(const [i,v]of h.vocabulary.entries()){out.push({...common,id:'hj:word:'+c.number+':'+h.hanja+':'+i,korean:v.korean,forms:[v.korean],answer:v.meaning||'Translation needs checking',quizAnswer:v.meaning||'Translation needs checking',hanjaRef:{...ref,page:v.page||h.page,vocabulary:true},memoryHint:{type:'Hanja word family',text:`${h.hanja} (${h.reading||''}) = ${h.meaning||h.koreanMeaning||''}. ${v.korean}${v.hanja?' · '+v.hanja:''}. Learn the shared root, then recall the whole word.`},note:`Book vocabulary · Chapter ${c.number} · printed p.${v.page||h.page}${v.hanja?' · '+v.hanja:''}. ${v.note||''}`})}}}return out}
 function seedReviews(){let changed=false;for(const w of words){if(state.curriculum.reviews[w.id])continue;if(w.studyRef){state.curriculum.reviews[w.id]={due:E.addDays(w.studyRef.date,1),interval:0,successes:0,lapses:0,lastDate:'',lastResult:false};changed=true;continue}const p=practice(w);if((w.hanjaRef&&state.curriculum.chapters[w.hanjaRef.chapterId])||(!w.hanjaRef&&(learned(w)||p.known+p.again>0))){state.curriculum.reviews[w.id]={due:today(),interval:0,successes:0,lapses:0,lastDate:'',lastResult:false};changed=true}}return changed}
 function schedule(w,known){state.curriculum.reviews[w.id]=E.review(state.curriculum.reviews[w.id],known,today())}
 const due=w=>!!state.curriculum?.reviews[w.id]&&state.curriculum.reviews[w.id].due<=today();
 function dailyBatch(){const c=state.curriculum,exists=!!c.reviewBatches[today()],batch=E.dailyReview(c,words,today(),state.daily,20);if(!exists)save();return batch}
 function open(next='today'){view=next;mode='plan';render()}
 function openStack(c){category=c;mode='cards';$('#unlearned').checked=false;resetDeck();render();$('#stackTitle').scrollIntoView({behavior:'smooth',block:'start'})}
 function nav(){return`<div class="hub-nav">${[['today','Today'],['hanja','Hanja book'],['notes','Book notes'],['books','Book sequence'],['calendar','Calendar'],['milestones','Levels & rewards']].map(([k,v])=>`<button class="small-btn ${view===k?'selected':''}" data-hub="${k}">${v}</button>`).join('')}</div>`}
 function examPanel(){const r=dates.result||{},u=dates.uaeRegistration||{},next=(dates.upcoming||[]).filter(x=>x.testStart>=today()).slice(0,3);return`<details class="exam-panel"><summary>✓ TOPIK I sat · Results ${dateLabel(r.date)} · TOPIK II dates</summary><div class="exam-grid"><div><h4>Your 108th TOPIK results</h4><strong>${dateLabel(r.date)}</strong><p>${r.timeDubai||'10:00'} Dubai · ${r.timeKorea||'15:00'} Korea</p><a href="${e(r.sourceUrl||'https://www.topik.go.kr/')}" target="_blank" rel="noopener">Official result schedule ↗</a></div><div><h4>Next TOPIK II in the UAE</h4><strong>Registration dates awaiting local confirmation</strong><p>Check the UAE organiser before booking. Korea’s application windows below do not apply to the UAE.</p><a href="${e(u.sourceUrl||'https://uae.korean-culture.org/')}" target="_blank" rel="noopener">UAE organiser’s notices ↗</a></div></div>${next.map(n=>`<p class="exam-row"><b>${e(n.title||'TOPIK')} · ${dateLabel(n.testStart)}${n.testEnd!==n.testStart?'–'+dateLabel(n.testEnd):''}</b><br>${e(n.scope||'')} · Registration ${dateLabel(n.registrationStart)}–${dateLabel(n.registrationEnd)} <strong>(Korea only)</strong>. UAE availability unconfirmed. <a href="${e(n.sourceUrl)}" target="_blank" rel="noopener">Official schedule ↗</a></p>`).join('')}<small>Checked ${e(dates.checkedAt||'2026-10-22')}. These are dated official notices, not a live registration feed.</small></details>`}
 function renderHub(){const box=$('#studyContent');$('#stackTitle').textContent='Your next chapter';$('#stackCount').textContent='TOPIK II · Levels 3 → 4';box.innerHTML=nav()+`<div id="hubBody"></div>`;document.querySelectorAll('[data-hub]').forEach(b=>b.onclick=()=>open(b.dataset.hub));if(view==='today')renderToday();if(view==='hanja')renderHanja();if(view==='notes')window.BookNotes.render();if(view==='books')renderBooks();if(view==='calendar')renderCalendar();if(view==='milestones')renderMilestones()}
 function currentPlan(){const c=state.curriculum;if(!c.dayPlans[today()]){c.dayPlans[today()]=E.makePlan(c,today(),hanja.chapters);const p=c.dayPlans[today()],session=c.sessions[today()]||{minutes:0,tasks:[],note:''};for(const [id,unit]of [['course',p.course],['exercises',p.exercise]])if(unit&&c.books[E.unitKey(unit)])session.tasks=[...new Set([...session.tasks,id])];c.sessions[today()]=session;save()}return c.dayPlans[today()]}
 function partLabel(u){return E.courseParts.find(p=>p.id===u?.part)?.label||u?.part||''}
 function lessonOptions(chapter,selected='bundle-1'){return E.bundles.map(bundle=>{const done=bundle.parts.filter(part=>state.curriculum.books[E.unitKey({chapter,part})]).length;return`<optgroup label="Lesson ${bundle.id.slice(-1)}"><option value="${bundle.id}" ${selected===bundle.id?'selected':''}>${bundle.label} · ${done}/4 complete</option>${bundle.parts.map(part=>`<option value="${part}" ${selected===part?'selected':''}>↳ ${partLabel({part})}${state.curriculum.books[E.unitKey({chapter,part})]?' ✓':''}</option>`).join('')}</optgroup>`}).join('')+E.courseParts.filter(p=>!E.bundleFor(p.id)).map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${p.label}</option>`).join('')+'<option value="whole">Whole chapter · all parts</option>'}
 function planLabels(p){const b=E.bundleFor(p.course?.part),chapter=p.course?.chapter;return{hanja:p.hanja.length?'Hanja · '+p.hanja.map(n=>'Chapter '+n).join(' + '):'Hanja · review your roots',course:chapter?`Chapter ${chapter} · ${b?.label||partLabel(p.course)}`:'TOPIK II guide practice',exercises:''}}
 function renderToday(){const c=state.curriculum,p=currentPlan();E.refreshPlan(c,p,hanja.chapters,c.sessions[today()]?.tasks||[]);const session=c.sessions[today()]||{minutes:0,tasks:[],note:''},batch=dailyBatch(),yesterday=E.yesterdayWords(words,today()),tasks=E.tasks(c.dailyMinutes,today()),s=E.streak(c.sessions,today()),chapter=p.course?.chapter||1,bundle=E.bundleFor(p.course?.part),selected=bundle?.id||p.course?.part||'bundle-1',next=E.makePlan(c,E.addDays(today(),1),hanja.chapters),done=t=>session.tasks.includes(t.id)||(t.id==='yesterday'&&!yesterday.length),count=tasks.filter(done).length;save();
 $('#hubBody').innerHTML=`${examPanel()}<div class="hub-metrics"><div><strong>${s.current} 🔥</strong><small>DAY STREAK</small></div><div><strong>${count}/5</strong><small>TODAY’S CHECKLIST</small></div><div><strong>${hanja.chapters.filter(h=>c.chapters[h.id]).length}/26</strong><small>HANJA CHAPTERS</small></div></div><article class="hub-card daily-intro"><div class="eyebrow">${dateLabel(today())} · YOUR DAILY STUDY</div><h3>Five small promises to yourself ♡</h3><label>Today’s study budget <select id="dailyMinutes">${[60,90,120].map(n=>`<option value="${n}" ${c.dailyMinutes===n?'selected':''}>${n} minutes</option>`).join('')}</select></label><progress max="5" value="${count}">${count}/5</progress></article>${tasks.map((t,i)=>`<article class="hub-card today-task ${done(t)?'is-done':''}"><div class="today-task-heading"><label><input type="checkbox" data-task="${t.id}" ${done(t)?'checked':''}><span class="task-number">0${i+1}</span><h3>${t.name}</h3></label><small>${t.minutes} min</small></div>${t.id==='review'?`<p>A fresh random selection each day. Familiar words can return on another day. Hanja is separate.</p><p class="quiet">${batch.filter(w=>(state.daily[today()]||[]).includes(w.id)).length}/${batch.length} reviewed today</p><div class="hub-actions"><button class="btn primary" id="reviewToday">Revise ${batch.length} words →</button><button class="small-btn" id="typeToday">⌨ Type the Korean</button></div>`:t.id==='yesterday'?`<p>Every vocabulary card added on ${dateLabel(E.addDays(today(),-1))}. This set has no 20-card limit.</p>${yesterday.length?`<div class="hub-actions"><button class="btn primary" id="learnYesterday">Learn all ${yesterday.length} words →</button><button class="small-btn" id="typeYesterday">⌨ Type yesterday’s words</button></div>`:'<p class="quiet">No vocabulary was added on that date. Add it below with yesterday’s study date if needed.</p>'}`:t.id==='hanja'?`<p>${e(planLabels(p).hanja)} is suggested. Choose any chapter you actually covered.</p><div class="planner-options"><label for="extraHanja">Hanja chapter covered<select id="extraHanja"><option value="">Choose a chapter…</option>${hanja.chapters.map(h=>`<option value="${h.number}">${h.number}. ${e(h.title)}${c.chapters[h.id]?' ✓':''}</option>`).join('')}</select></label><button class="btn" id="saveHanja">Save chapter covered</button></div><p class="quiet">Saved today: ${(session.coveredHanja||[]).join(', ')||'none yet'}</p><button class="text-link" id="openHanja">Open Hanja book →</button>`:t.id==='course'?`<p>Complete one grammar lesson with its quiz, conversation and vocabulary, or select an individual part.</p><div class="planner-options"><label for="extraCourse">Student book chapter<select id="extraCourse">${courseTitles.map((name,i)=>`<option value="${i+1}" ${chapter===i+1?'selected':''}>${i+1}. ${e(name)}</option>`).join('')}</select></label><label for="coveredPart">Lesson or part covered<select id="coveredPart">${lessonOptions(chapter,selected)}</select></label></div><div class="hub-actions"><button class="btn primary" id="saveStudent">Save lesson covered</button><button class="text-link" id="undoStudent">Undo selected completion</button></div><p class="quiet">Saved today: ${(session.coveredParts||[]).map(u=>'Ch. '+u.chapter+' · '+partLabel(u)).join(', ')||'none yet'}</p>`:`<p>Type Korean, select the chapter, and press Enter. A translation is added to your chapter cards automatically.</p>${window.Vocabulary.form(chapter)}`}</article>`).join('')}<article class="hub-card"><h3>Keep your streak honest</h3><label>Minutes actually studied<input id="actualMinutes" type="number" min="1" max="240" value="${session.minutes||c.dailyMinutes}"></label><label class="session-field">A note for yourself<textarea id="sessionNote" maxlength="1500">${e(session.note||'')}</textarea></label><button class="btn primary" id="logToday">Save today’s study time ♡</button><p class="quiet">Checklist and chapter choices save immediately. Saving actual minutes records your study streak.</p></article><article class="hub-card"><h3>Next session · based on completed work</h3><p>${e(planLabels(next).hanja)}<br>${e(planLabels(next).course)}</p><p class="quiet">Completed parts are kept. The plan continues from the first unfinished part in the book.</p></article>`;
 const saveNote=()=>{const s=c.sessions[today()]||{minutes:0,tasks:[],note:''};s.note=$('#sessionNote').value;c.sessions[today()]=s;save()};$('#sessionNote').oninput=saveNote;
 $('#dailyMinutes').onchange=()=>{saveNote();c.dailyMinutes=+$('#dailyMinutes').value;save();renderToday()};const start=(stack,typing=false)=>{openStack(stack);if(typing){mode='typing';render()}};$('#reviewToday').onclick=()=>start('Daily review');$('#typeToday').onclick=()=>start('Daily review',true);if($('#learnYesterday'))$('#learnYesterday').onclick=()=>start('Yesterday words');if($('#typeYesterday'))$('#typeYesterday').onclick=()=>start('Yesterday words',true);$('#openHanja').onclick=()=>open('hanja');
 document.querySelectorAll('[data-task]').forEach(b=>b.onchange=()=>{saveNote();const s=c.sessions[today()];s.tasks=[...document.querySelectorAll('[data-task]:checked')].map(b=>b.dataset.task);seedReviews();save();renderToday()});
 $('#saveHanja').onclick=()=>{saveNote();const n=+$('#extraHanja').value;if(!n)return toast('Choose a chapter first.');E.recordCoveredChapter(c,today(),'hanja',n);c.sessions[today()].tasks=[...new Set([...c.sessions[today()].tasks,'hanja'])];seedReviews();save();renderToday();toast('Hanja chapter saved ♡')};
 $('#extraCourse').onchange=()=>{$('#coveredPart').innerHTML=lessonOptions(+$('#extraCourse').value)};
 const recordStudent=completed=>{saveNote();const chapter=+$('#extraCourse').value,part=$('#coveredPart').value;if(part==='whole'){E.setCourseChapter(c,chapter,completed);if(completed)E.recordCoveredChapter(c,today(),'course',chapter)}else if(part.startsWith('bundle-'))E.completeBundle(c,today(),chapter,part,completed);else E.recordCoursePart(c,today(),chapter,part,completed);const bundle=E.bundles.find(b=>b.id===part)||E.bundleFor(part),whole=part==='whole'||bundle&&bundle.parts.every(id=>c.books[E.unitKey({chapter,part:id})]);const s=c.sessions[today()];s.tasks=s.tasks.filter(id=>id!=='course');if(completed&&whole)s.tasks.push('course');if(!completed&&part==='whole')s.coveredCourse=(s.coveredCourse||[]).filter(n=>n!==chapter);p.course=E.nextCourse(c);save();renderToday();toast(completed?'Textbook lesson saved ♡':'Selected completion undone.')};$('#saveStudent').onclick=()=>recordStudent(true);$('#undoStudent').onclick=()=>recordStudent(false);
 $('#logToday').onclick=()=>{const minutes=+$('#actualMinutes').value;if(!Number.isInteger(minutes)||minutes<1||minutes>240)return toast('Enter 1–240 minutes.');saveNote();c.sessions[today()].minutes=minutes;save();renderToday();toast('Study time saved. A little promise kept ♡')};window.Vocabulary.bind();}
 function renderHanja(){const c=state.curriculum,current=hanja.chapters.find(x=>x.id===chapterId)||hanja.chapters[0];if(!current){$('#hubBody').innerHTML='<p>Hanja import is still being checked.</p>';return}const next=E.nextChapter(hanja.chapters,c.chapters);$('#hubBody').innerHTML=`<p class="hub-lead">Useful Hanja for Learners of Korean · ${hanja.chapters.length} chapters · ${hanja.chapters.reduce((n,c)=>n+c.characters.length,0)} character entries</p><p class="quiet">Chapters 1–4 start completed as you requested; Chapter 5 is next. Chapter completion and individual card recall are tracked separately.</p><div class="hanja-chapters">${hanja.chapters.map(x=>`<button class="small-btn ${x.id===current.id?'selected':''}" data-chapter="${e(x.id)}">${c.chapters[x.id]?'✓ ':next?.id===x.id?'→ ':''}${x.number}. ${e(x.title)}</button>`).join('')}</div><article class="hub-card"><div class="eyebrow">${e(current.section)} · CHAPTER ${current.number}</div><h3>${e(current.title)}</h3><div class="hub-actions"><button class="btn primary" id="studyChapter">Study chapter cards →</button><button class="small-btn" id="studyAllHanja">Study all Hanja</button><button class="small-btn" id="reviewHanja">Review Hanja due</button><button class="small-btn" id="chapterComplete">${c.chapters[current.id]?'Mark chapter still studying':'Mark chapter completed ✓'}</button></div><input class="search" id="hanjaSearch" aria-label="Search Hanja and Korean vocabulary" placeholder="Search this chapter: character, Korean or meaning…" value="${e(hanjaSearch)}"><div id="hanjaCharacters"></div></article><p class="quiet">Every entry keeps its book page. Repeated character appearances remain in their original chapter. A chapter may include Korean words that use several roots.</p>`;
 document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{chapterId=b.dataset.chapter;hanjaSearch='';renderHanja()});$('#studyChapter').onclick=()=>openStack('Hanja · Chapter '+current.number);$('#studyAllHanja').onclick=()=>openStack('Hanja');$('#reviewHanja').onclick=()=>openStack('Hanja reviews');$('#chapterComplete').onclick=()=>{c.chapters[current.id]=!c.chapters[current.id];if(!c.chapters[current.id]&&c.dayPlans[today()]?.hanja.includes(current.number)&&c.sessions[today()])c.sessions[today()].tasks=c.sessions[today()].tasks.filter(id=>id!=='hanja');if(c.chapters[current.id])seedReviews();save();renderHanja()};$('#hanjaSearch').oninput=()=>{hanjaSearch=$('#hanjaSearch').value;fillHanja(current)};fillHanja(current);}
 function fillHanja(c){const q=hanjaSearch.toLowerCase();$('#hanjaCharacters').innerHTML=c.characters.filter(h=>JSON.stringify(h).toLowerCase().includes(q)).map(h=>`<details class="hanja-entry"><summary><b lang="ko">${e(h.hanja)}</b><span>${e(h.koreanMeaning||'')} ${e(h.reading||'')} · ${e(h.meaning||'')}</span><small>p.${h.page}</small></summary><div class="hanja-vocab">${h.vocabulary.map(v=>`<div><strong lang="ko">${e(v.korean)}</strong><span>${e(v.hanja||'')}</span><span>${e(v.meaning||'')}</span><small>p.${v.page||h.page}</small></div>`).join('')||'<p>Character study entry; no separate vocabulary list in this entry.</p>'}</div></details>`).join('')||'<p>No matching roots in this chapter.</p>'}
 function renderBooks(){const c=state.curriculum;$('#hubBody').innerHTML=`<p class="hub-lead">One main course. Hanja alongside it. Exam practice introduced gradually.</p><article class="hub-card"><div class="eyebrow">PARALLEL TRACK · KEEP GOING NOW</div><h3>Useful Hanja for Learners of Korean</h3><p>10–20 minutes daily. Continue Chapter 5, connect each root to its Korean words, and review due cards. You do not need to finish the entire Hanja book before starting your course.</p><button class="text-link" id="bookHanja">Open Hanja book →</button></article><article class="hub-card"><div class="eyebrow">1 · FOUNDATION · FOLLOW YOUR PART LOG</div><h3>Korean Made Easy — Intermediate</h3><p>Your main textbook. Work on one grammar point per session, with a short quiz and dialogue as time allows. Log each part separately. Chapter completion means all its parts are covered: dialogue → grammar in context → exercises → 5 sentences about your own life. On the second pass, listen and speak without the text.</p><details><summary>Track the 15 course chapters</summary><div class="book-checks">${courseTitles.map((t,i)=>`<label><input type="checkbox" data-course="${i+1}" ${c.books['course-'+(i+1)]?'checked':''}> ${i+1}. ${t} · p.${17+i*16}</label>`).join('')}</div></details><label><input type="checkbox" data-book="course" ${c.books.course?'checked':''}> Main course completed and reviewed</label></article><article class="hub-card"><div class="eyebrow">2 · INTRODUCE IN WEEK 3–4 · FOCUS IN WEEKS 9–16</div><h3>Complete Guide to the TOPIK II — 3rd Edition</h3><p>Learn one question type at a time. Work untimed first, explain why the distractors are wrong, then add a time limit. Practise writing from the start; get feedback on questions 51–53 before making 54 your main focus.</p><label><input type="checkbox" data-book="guide" ${c.books.guide?'checked':''}> Question-type guide completed and reviewed</label></article><article class="hub-card"><div class="eyebrow">3 · WHEN THE TYPES FEEL FAMILIAR</div><h3>SD Edu TOPIK II 실전 모의고사</h3><p>Extra timed papers after the guide. Start with one timed section a week; later sit a full PBT mock every two weeks and spend another session correcting it. Use official released papers too. This is optional extra practice, not another main course.</p><label><input type="checkbox" data-book="mocks" ${c.books.mocks?'checked':''}> Mock-test collection reviewed</label></article><article class="hub-card"><h3>A realistic pace, with checkpoints</h3><p>At 1–2 focused hours a day, use 16 weeks as a first Level 3 checkpoint and 28 weeks as a Level 4 checkpoint. These are planning estimates from a beginner foundation, not score promises. Adjust after your first timed mock and every four weeks.</p><label>Plan start <input type="date" id="planStart" value="${c.startDate}"></label><button class="small-btn" id="savePlanStart">Update checkpoints</button><p>Level 3 checkpoint: <b>${dateLabel(E.addDays(c.startDate,112))}</b><br>Level 4 checkpoint: <b>${dateLabel(E.addDays(c.startDate,196))}</b></p><p class="quiet">Study rhythm: Mon/Tue course + listening; Wed reading + writing; Thu/Fri course + listening; Sat writing feedback + catch-up; Sun timed section + review. Daily Hanja and spaced recall continue throughout.</p></article>`;
 $('#bookHanja').onclick=()=>open('hanja');document.querySelectorAll('[data-book]').forEach(b=>b.onchange=()=>{c.books[b.dataset.book]=b.checked;save()});document.querySelectorAll('[data-course]').forEach(b=>b.onchange=()=>{E.setCourseChapter(c,+b.dataset.course,b.checked);if(!b.checked){const p=c.dayPlans[today()],session=c.sessions[today()];if(p?.course?.chapter===+b.dataset.course&&session)session.tasks=session.tasks.filter(id=>!['course','exercises'].includes(id))}save()});$('#savePlanStart').onclick=()=>{if(!E.validDate($('#planStart').value)){toast('Choose a valid start date.');return}c.startDate=$('#planStart').value;save();renderBooks()};}
 function renderCalendar(){const c=state.curriculum,first=month+'-01',date=new Date(first+'T12:00:00Z'),offset=(date.getUTCDay()+6)%7,days=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).getUTCDate(),s=E.streak(c.sessions,today());$('#hubBody').innerHTML=`<div class="calendar-head"><button class="small-btn" id="monthPrev" aria-label="Previous month">←</button><h3>${date.toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'UTC'})}</h3><button class="small-btn" id="monthNext" aria-label="Next month">→</button></div><p class="quiet">${s.current}-day current streak · best ${s.best} · ${s.total} study days. Dates use Dubai time. Select a date to plan or log study.</p><div class="calendar-grid">${['M','T','W','T','F','S','S'].map(d=>`<span class="weekday">${d}</span>`).join('')}${Array.from({length:offset},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const d=month+'-'+String(i+1).padStart(2,'0'),sess=c.sessions[d],event=dates.result?.date===d?'Results':(dates.upcoming||[]).some(x=>x.registrationStart===d)?'Korea reg.':(dates.upcoming||[]).some(x=>x.testStart===d)?'TOPIK':'';return`<button data-date="${d}" class="calendar-date ${d===today()?'today':''} ${d===selectedDay?'selected':''} ${sess?.minutes?'studied':''}"><b>${i+1}</b><small>${sess?.minutes?sess.minutes+' min':c.calendar[d]?.note?'Planned':''}</small>${event?`<em>${event}</em>`:''}</button>`}).join('')}</div><div id="calendarDay"></div>`;
 $('#monthPrev').onclick=()=>changeMonth(-1);$('#monthNext').onclick=()=>changeMonth(1);document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selectedDay=b.dataset.date;renderCalendar()});renderCalendarDay();}
 function changeMonth(n){const d=new Date(month+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+n);month=d.toISOString().slice(0,7);selectedDay=month+'-01';renderCalendar()}
 function renderCalendarDay(){const c=state.curriculum,day=selectedDay||today(),plan=c.calendar[day]||{minutes:c.dailyMinutes,note:''},session=c.sessions[day]||{minutes:0,tasks:[],note:''},future=day>today();$('#calendarDay').innerHTML=`<article class="hub-card"><h3>${dateLabel(day)} ${day===today()?'· Today':''}</h3>${day===dates.result?.date?'<p>108th TOPIK results · 10:00 Dubai. Check the official site.</p>':''}<details class="calendar-suggest"><summary>Suggested ${plan.minutes}-minute routine</summary>${E.tasks(plan.minutes,day).map(t=>`<p>${e(planLabels(c.dayPlans[day]||E.makePlan(c,day,hanja.chapters))[t.id]||t.name)} · ${t.minutes} min</p>`).join('')}</details><label class="session-field">Plan for this day<textarea id="dayPlan" maxlength="1000" placeholder="Chapter, exercise, feedback or a rest day…">${e(plan.note)}</textarea></label><label>Planned minutes <select id="dayBudget">${[60,90,120].map(n=>`<option value="${n}" ${plan.minutes===n?'selected':''}>${n}</option>`).join('')}</select></label><button class="small-btn" id="saveDayPlan">Save plan</button>${!future?`<hr><label class="session-field">Actual study minutes <input id="dayActual" type="number" min="0" max="240" value="${session.minutes}"></label><label class="session-field">Session note<textarea id="daySessionNote" maxlength="1500">${e(session.note)}</textarea></label><button class="btn primary" id="saveDaySession">Save actual study</button><p class="quiet">0 minutes removes study credit for this date; it does not delete vocabulary practice. Future sessions cannot be credited early.</p>`:'<p>Plan ahead; log actual study on or after this date.</p>'}</article>`;$('#saveDayPlan').onclick=()=>{c.calendar[day]={minutes:+$('#dayBudget').value,note:$('#dayPlan').value};save();renderCalendar();toast('Plan saved ♡')};if(!future)$('#saveDaySession').onclick=()=>{const n=+$('#dayActual').value;if(!Number.isInteger(n)||n<0||n>240){toast('Enter 0–240 actual minutes.');return}c.sessions[day]={...session,minutes:n,note:$('#daySessionNote').value};save();renderCalendar();toast('Study log saved ♡')};}
 const rewards=[['start','First saved session','Make your favourite tea',c=>Object.values(c.sessions).some(s=>s.minutes>0)],['week','7-day streak','A café study date or a small treat',c=>E.streak(c.sessions,today()).best>=7],['hanja8','8 Hanja chapters completed','Buy yourself a small stationery gift',c=>hanja.chapters.filter(x=>c.chapters[x.id]).length>=8],['course','Intermediate course completed','A Korean film night or dinner date',c=>c.books.course],['month','30 study days','Plan a day out with your husband',c=>E.streak(c.sessions,today()).total>=30],['level3','Level 3 practice readiness','A special date or a book you want',c=>E.readiness(c,3).percent===100],['level4','Level 4 practice readiness','Celebrate with a memorable experience',c=>E.readiness(c,4).percent===100]];
 function renderMilestones(){const c=state.curriculum;$('#hubBody').innerHTML=`<p class="hub-lead">Track the work and the evidence. A practice milestone is not an official TOPIK result.</p><div class="levels-grid">${[3,4].map(n=>{const r=E.readiness(c,n);return`<article class="hub-card"><h3>TOPIK Level ${n}</h3><div class="level-score">${r.percent}% <small>readiness checklist</small></div><progress max="100" value="${r.percent}">${r.percent}%</progress><p>PBT pass threshold: <b>${r.officialThreshold}/300</b><br>Our practice buffer: <b>${r.practiceTarget}/300</b></p>${r.checks.map(x=>`<p>${x.done?'✓':'○'} ${e(x.label)}</p>`).join('')}<label><input type="checkbox" data-writing="writing${n}" ${c.skills['writing'+n]?'checked':''}> Writing practice above completed with feedback</label></article>`}).join('')}</div><p class="quiet">PBT thresholds verified with <a href="${e(dates.thresholds?.sourceUrl||'https://www.topik.go.kr/')}" target="_blank" rel="noopener">NIIED ↗</a>. This tracker uses PBT scores only; IBT has a different scale. Mock scores are self-reported.</p><article class="hub-card"><h3>Log a timed PBT mock</h3><div class="mock-form"><label>Date <input type="date" id="mockDate" value="${today()}"></label><label>Paper / book <input id="mockName" maxlength="120" placeholder="e.g. Guide · Mock 1"></label>${['Listening','Reading','Writing'].map(t=>`<label>${t} /100 <input type="number" min="0" max="100" id="mock${t}" value="0"></label>`).join('')}</div><button class="btn primary" id="addMock">Save mock score</button><div class="mock-history">${[...c.mocks].reverse().map(m=>`<p><b>${dateLabel(m.date)} · ${e(m.name)}</b><br>${m.listening+m.reading+m.writing}/300 · L ${m.listening} / R ${m.reading} / W ${m.writing} <button class="text-link" data-remove-mock="${e(m.id)}">Remove score</button></p>`).join('')||'<p>No mock scores yet. Your first paper is a baseline, not a verdict.</p>'}</div></article><h3>Little milestones, real celebrations ♡</h3><div class="reward-grid">${rewards.map(([id,label,gift,unlocked])=>{const yes=unlocked(c);return`<article class="hub-card reward ${yes?'unlocked':''}"><small>${c.rewards[id]?'✓ CELEBRATED':yes?'✿ UNLOCKED':'○ KEEP GOING'}</small><h4>${label}</h4><p>${gift}</p><button class="small-btn" data-reward="${id}" ${!yes&&!c.rewards[id]?'disabled':''}>${c.rewards[id]?'Mark not celebrated':'I celebrated this ♡'}</button></article>`}).join('')}</div>`;
 document.querySelectorAll('[data-writing]').forEach(b=>b.onchange=()=>{c.skills[b.dataset.writing]=b.checked;save();renderMilestones()});$('#addMock').onclick=()=>{const day=$('#mockDate').value,name=$('#mockName').value.trim(),scores=['Listening','Reading','Writing'].map(t=>+$('#mock'+t).value);if(!E.validDate(day)||day>today()||!name||scores.some(n=>!Number.isInteger(n)||n<0||n>100)){toast('Use a past/today date, paper name, and scores from 0–100.');return}c.mocks.push({id:crypto.randomUUID(),date:day,name,format:'PBT',listening:scores[0],reading:scores[1],writing:scores[2]});save();renderMilestones();toast('Mock saved. Let the errors guide your next session. ♡')};document.querySelectorAll('[data-remove-mock]').forEach(b=>b.onclick=()=>{c.mocks=c.mocks.filter(m=>m.id!==b.dataset.removeMock);save();renderMilestones()});document.querySelectorAll('[data-reward]').forEach(b=>b.onclick=()=>{c.rewards[b.dataset.reward]=!c.rewards[b.dataset.reward];save();renderMilestones()});}
 return{init,cards,dailyBatch,open,openStack,render:renderHub,schedule,due,seedReviews,isLegacy:legacy,examPanel,getChapters:()=>hanja.chapters};
})();
